import{_ as a,o as t,c as s,a4 as o}from"./chunks/framework.C83Ss68L.js";const u=JSON.parse('{"title":"ADR-0006: Retire the Telegram and WhatsApp adapters","description":"Both channel adapters are removed from the exports map in 6.11.2; the rule in ADR-0003 stands, its list is shorter.","frontmatter":{"title":"ADR-0006: Retire the Telegram and WhatsApp adapters","description":"Both channel adapters are removed from the exports map in 6.11.2; the rule in ADR-0003 stands, its list is shorter."},"headers":[],"relativePath":"explanation/decisions/adr-0006-retire-telegram-whatsapp-adapters.md","filePath":"explanation/decisions/adr-0006-retire-telegram-whatsapp-adapters.md","lastUpdated":1792321993000}'),r={name:"explanation/decisions/adr-0006-retire-telegram-whatsapp-adapters.md"};function n(d,e,i,c,p,h){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-0006-retire-the-telegram-and-whatsapp-adapters" tabindex="-1">ADR-0006: Retire the Telegram and WhatsApp adapters <a class="header-anchor" href="#adr-0006-retire-the-telegram-and-whatsapp-adapters" aria-label="Permalink to &quot;ADR-0006: Retire the Telegram and WhatsApp adapters&quot;">​</a></h1><p><strong>Status:</strong> Accepted · <strong>Date:</strong> 2026-10-18 (released in <strong>6.11.2</strong>) <strong>Amends:</strong> <a href="/katanakit-js/explanation/decisions/adr-0003-adapter-subpath-exports">ADR-0003</a></p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>ADR-0003 publishes every framework adapter only through the <code>exports</code> map, so <code>/telegram</code> and <code>/whatsapp</code> became public subpath API. Both then carried defects that the Safe Result contract exists to prevent:</p><ul><li><code>useSendMessage</code> and <code>useSendWhatsAppMessage</code> returned a bare <code>Promise&lt;Response&gt;</code> from a raw third-party <code>fetch</code>, and no caller inspected <code>response.ok</code>. A revoked token, a <code>429</code>, or a provider <code>4xx</code> was indistinguishable from success — the assistant reported <code>ok</code>, nothing was delivered, and no error surfaced.</li><li>The WhatsApp webhook acknowledged <code>200</code> <strong>before</strong> attempting the reply (&quot;ack fast so Meta does not retry&quot;), so a failed send could never be retried by the provider and never surfaced an error on either end.</li><li>Both adapters depended on <code>express-rate-limit</code>, which was declared as a hard runtime <code>dependency</code> even though it is reachable only from subpath adapters.</li></ul><p>The adapters were never used by the maintainer. The maintenance cost was real and the correctness cost was a silent failure mode, not a loud one.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Remove <code>src/adapters/telegram/</code> and <code>src/adapters/whatsapp/</code>, their tests, their guide pages, and the <code>./adapters/telegram</code> and <code>./adapters/whatsapp</code> entries from <code>package.json#exports</code>. The assistant keeps its REST channel, its session store and its free-form <code>channel</code> tag — only the two shipped channel implementations go away.</p><p>In the same change, <code>express-rate-limit</code> moves from <code>dependencies</code> to <code>peerDependencies</code> with <code>peerDependenciesMeta.optional</code>, and is pinned in <code>devDependencies</code> so the repository still resolves it. It is statically imported by <code>src/adapters/assistant</code>, so a consumer of <code>katanakit-js/adapters/assistant</code> must install it — exactly as they already must for <code>express</code> and <code>cors</code>. This closes the ADR-0003 peer-dependency rule violation for every remaining adapter.</p><p>This is a <strong>breaking change</strong>: the subpaths were declared in <code>exports</code>, so a consumer importing them on <code>^6.11.2</code> gets <code>ERR_PACKAGE_PATH_NOT_EXPORTED</code> without ever having agreed to a major. It shipped as a patch release and its commit subjects were typed <code>fix:</code>, which understates it for anyone scanning the changelog for removals. ADR-0003&#39;s <em>rule</em> — every adapter lives on a subpath, every framework is an optional peer — is unchanged and still applies to the 24 remaining subpaths. Only its enumeration shrinks.</p><p>ADR-0003 is left untouched on purpose. Its list was accurate when written, and a superseded record is not rewritten; this record amends it.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Better.</strong> Two adapters that failed silently are gone instead of patched. The <code>exports</code> map no longer advertises entry points that no one uses. The assistant&#39;s channel surface is one transport instead of three, and the example in <code>examples/assistant</code> no longer branches on <code>KITT_CHANNEL</code>.</p><p><strong>Worse.</strong> Anyone importing <code>katanakit-js/adapters/telegram</code> or <code>/adapters/whatsapp</code> gets <code>ERR_PACKAGE_PATH_NOT_EXPORTED</code> on upgrade and must pin <code>^6</code> or call the provider API directly. The assistant loses its long-polling channel, which needed no public URL, and its Meta webhook integration with <code>X-Hub-Signature-256</code> verification.</p><p><strong>Also fixed here.</strong> <code>express-rate-limit</code> is no longer a hard runtime <code>dependency</code>. It is an optional peer, declared alongside <code>express</code> and <code>cors</code>, which the assistant adapter already required.</p><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="/katanakit-js/explanation/decisions/adr-0003-adapter-subpath-exports">ADR-0003 — adapter subpath exports</a></li><li><a href="/katanakit-js/guides/architecture">Architecture</a> — the exports map in context.</li><li><a href="/katanakit-js/guides/assistant">Assistant (Kitt)</a> — the surviving REST channel.</li><li><a href="/katanakit-js/guides/upgrade-to/v6">Upgrade to v6</a> — the v6 rename tables, annotated.</li></ul>',17)])])}const m=a(r,[["render",n]]);export{u as __pageData,m as default};
